def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    decline = old_value - new_value

    return {
        "value": decline,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "decline": decline,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
